parts.text:
[
  {
    "statement": "Areas receiving organic fertilizers often supported higher earthworm abundance, diversity, biomass, and density compared to areas receiving mineral fertilizers.",
    "citations": [
      "134"
    ]
  },
  {
    "statement": "The use of organic fertilizers instead of mineral fertilizers often increased the abundance and/or species richness of some or all invertebrates studied.",
    "citations": [
      "134"
    ]
  },
  {
    "statement": "Some studies on different fertilizer regimes reported no long-term or only local-scale effects on invertebrates.",
    "citations": [
      "134"
    ]
  },
  {
    "statement": "Heavy slurry applications were reported as being potentially toxic to common earthworms.",
    "citations": [
      "134"
    ]
  },
  {
    "statement": "Evidence on the effects of reducing fertilizer inputs on invertebrates was mixed.",
    "citations": [
      "139"
    ]
  },
  {
    "statement": "Some studies reported that reducing fertilizer inputs had positive effects on invertebrates.",
    "citations": [
      "139"
    ]
  },
  {
    "statement": "Other studies found that reducing fertilizer inputs had no or inconsistent effects on invertebrates.",
    "citations": [
      "139"
    ]
  },
  {
    "statement": "Two UK studies reported higher earthworm biomass or abundance in areas where fertilizer inputs were not reduced.",
    "citations": [
      "139"
    ]
  },
  {
    "statement": "Reducing two or more inputs, such as fertilizers combined with herbicides or pesticides, often showed positive effects on invertebrates and soil organisms.",
    "citations": [
      "139"
    ]
  },
  {
    "statement": "When reducing two or more inputs like fertilizers and pesticides, negative or null effects on invertebrates and soil organisms were also recorded.",
    "citations": [
      "139"
    ]
  },
  {
    "statement": "In permanent grasslands, stopping fertilizer inputs increased plant species richness.",
    "citations": [
      "694"
    ]
  },
  {
    "statement": "In several studies conducted in permanent grasslands, stopping fertilizer inputs attracted a higher abundance or species richness of some or all invertebrates.",
    "citations": [
      "694"
    ]
  },
  {
    "statement": "One review reported that unfertilized plots had higher densities of some invertebrates than nitrogen-fertilized plots.",
    "citations": [
      "694"
    ]
  },
  {
    "statement": "Another review found no clear effect on the density of soil-dwelling invertebrates resulting from fertilization practices.",
    "citations": [
      "694"
    ]
  },
  {
    "statement": "One replicated UK study observed lower invertebrate abundance under reduced fertilizer inputs, but the differences were not significant.",
    "citations": [
      "694"
    ]
  }
]

[
  {
    "statement": "Available action documents report no captured evidence on the effects of applying cross compliance environmental standards linked to all subsidy payments on farmland wildlife.",
    "citations": [
      "70"
    ]
  },
  {
    "statement": "There are no studies comparing cross compliance with other ways of implementing agri-environmental measures or monitoring before-and-after impacts, apart from the Swiss Ecological Compensation Areas scheme.",
    "citations": [
      "173"
    ]
  },
  {
    "statement": "Implementing food labelling schemes relating to biodiversity-friendly farming has no captured evidence for effects on farmland wildlife or bird populations.",
    "citations": [
      "71",
      "170"
    ]
  },
  {
    "statement": "Providing or retaining set-aside areas in farmland shows multiple studies where more species or higher densities used set-aside than crops.",
    "citations": [
      "175"
    ]
  },
  {
    "statement": "Some studies found fewer species or lower densities of wildlife in set-aside areas compared to crop areas.",
    "citations": [
      "175"
    ]
  },
  {
    "statement": "The productivity effects of providing or retaining set-aside areas in farmland were mixed.",
    "citations": [
      "175"
    ]
  },
  {
    "statement": "Naturally regenerated set-aside areas held more birds and species than sown set-aside areas.",
    "citations": [
      "175"
    ]
  }
]

[
  {
    "statement": "No relevant action documents were found that directly evaluate the effects of precision agriculture techniques on soil invertebrate populations.",
    "citations": []
  },
  {
    "statement": "No relevant action documents were found that compare the effects of precision agriculture techniques, such as GPS-guided variable rate fertilizer application, on soil invertebrate populations with standard uniform application methods.",
    "citations": []
  }
]
